    "statement": "Órgão público municipal realiza compra de ambulâncias: após reserva da dotação e emissão da nota de empenho em outubro, o fornecedor entrega os veículos em novembro e o fiscal do contrato atesta as notas fiscais; em dezembro, o tesoureiro transfere o dinheiro ao fornecedor.",
