    "justification": "A execução da despesa pública orçamentária (Arts. 58-64 da Lei nº 4.320/1964) segue a ordem rigorosa: (1) Empenho (reserva dotação e cria obrigação; vedada despesa sem prévio empenho); (2) Liquidação (verifica o direito adquirido do credor e atesta o recebimento); (3) Pagamento (ordem bancária após regular liquidação).",
