        "explanation": "Nos termos do Art. 3º, parágrafo único, da Lei nº 4.320/1964, as operações de crédito por antecipação da receita (ARO), as emissões de papel-moeda e outras entradas compensatórias no ativo e passivo financeiros (como cauções, fianças, depósitos judiciais e consignações) NÃO integram a receita orçamentária — são entradas EXTRAORÇAMENTÁRIAS!"
