    "justification": "Despesas Obrigatórias (pessoal, previdência, BPC, dívida) decorrem de lei/CF e são imunes a contingenciamento (Art. 9º, § 2º, LRF). Despesas Discricionárias comportam juízo de oportunidade e contingenciamento (inclusive emendas impositivas proporcionalmente — Art. 166, § 18, CF). Crédito orçamentário (autorização legal na LOA) não se confunde com recurso financeiro (dinheiro em caixa).",
